-- Solo perfil local. Formularios y plantillas que la Gerencia de Rentas publica para descarga (HU049).
-- Antes vivían como archivos y datos fijos del front; ahora están en la BD como cualquier formulario publicado.
-- Solo se cargan si el código aún no existe, para no pisar lo que se publique o retire desde la pantalla.

WITH plantilla AS (
    INSERT INTO operativo.plantilla_documento (codigo, nombre, tipo, descripcion)
    VALUES ('PL-001', 'Constancia de No Adeudo', 'FORMULARIO_MANUAL', 'Formato de referencia para la emisión de la Constancia de No Adeudo.')
    ON CONFLICT (codigo) DO NOTHING
    RETURNING id_plantilla
)
INSERT INTO operativo.version_plantilla
    (id_plantilla, numero_version, archivo, fecha_publicacion, vigente, tipo_contenido, contenido)
SELECT p.id_plantilla, 2, 'PL-001-v2.docx', TIMESTAMP WITH TIME ZONE '2026-10-19 09:00:00-05', TRUE,
       'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
       decode('', 'base64')
FROM plantilla p;

